// ── Dates ──────────────────────────────────────────────────────────────────────

// YYYY-MM-DD in the user's own timezone (toISOString would give the UTC date)
export function localDateKey(d = new Date()) {
  const date = new Date(d)
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`
}
export function todayKey() {
  return localDateKey()
}

// ── Formatting ────────────────────────────────────────────────────────────────

export function fmtTime(s) {
  return `${String(Math.floor(s / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`
}

// ── Exercise icons ────────────────────────────────────────────────────────────

export function getExerciseIcon(ex) {
  if (!ex) return 'mdi:weight-lifter'
  const name = ex.name?.toLowerCase() || ''
  const muscle = ex.muscle || ''
  const equip  = ex.equipment || ''

  // Name-specific overrides for best accuracy
  if (name.includes('deadlift'))          return 'mdi:weight-lifter'
  if (name.includes('squat'))             return 'mdi:human-handsdown'
  if (name.includes('bench press'))       return 'mdi:weight-lifter'
  if (name.includes('pull-up') || name.includes('pullup') || name.includes('chin-up')) return 'mdi:human-handsup'
  if (name.includes('dip'))               return 'mdi:human-handsup'
  if (name.includes('push-up') || name.includes('pushup')) return 'mdi:human'
  if (name.includes('plank'))             return 'mdi:human'
  if (name.includes('crunch') || name.includes('sit-up') || name.includes('situp')) return 'mdi:yoga'
  if (name.includes('row'))               return 'mdi:rowing'
  if (name.includes('curl'))              return 'mdi:arm-flex'
  if (name.includes('extension') && muscle === 'Triceps') return 'mdi:arm-flex-outline'
  if (name.includes('press') && muscle === 'Shoulders')   return 'mdi:weight-lifter'
  if (name.includes('raise'))             return 'mdi:human-greeting'
  if (name.includes('lunge') || name.includes('step'))    return 'mdi:walk'
  if (name.includes('run') || name.includes('sprint') || name.includes('jog')) return 'mdi:run'
  if (name.includes('jump') || name.includes('box'))      return 'mdi:run-fast'
  if (name.includes('hip thrust') || name.includes('glute bridge')) return 'mdi:human'
  if (name.includes('leg press'))         return 'mdi:seat-recline-extra'
  if (name.includes('leg curl') || name.includes('leg extension')) return 'mdi:human-handsdown'
  if (name.includes('calf'))              return 'mdi:walk'
  if (name.includes('bike'))              return 'mdi:bike'
  if (name.includes('elliptical'))        return 'mdi:run'
  if (name.includes('stair'))             return 'mdi:stairs'
  if (name.includes('rower'))             return 'mdi:rowing'
  if (name.includes('treadmill') || name.includes('walk') || name.includes('zone 2')) return 'mdi:walk'
  if (name.includes('swim'))              return 'mdi:swim'
  if (name.includes('stretch') || name.includes('pose') || name.includes('yoga') ||
      name.includes('flow') || name.includes('cat-cow') || name.includes('90/90')) return 'mdi:yoga'
  if (name.includes('carry'))             return 'mdi:bag-personal'
  if (name.includes('swing'))             return 'mdi:kettlebell'
  if (name.includes('burpee') || name.includes('jack') || name.includes('climber') ||
      name.includes('shuttle') || name.includes('bound') || name.includes('rope')) return 'mdi:run-fast'
  if (name.includes('dead bug') || name.includes('bird dog') || name.includes('hollow') ||
      name.includes('rollout') || name.includes('leg raise') || name.includes('pallof')) return 'mdi:yoga'
  if (name.includes('hang'))              return 'mdi:human-handsup'

  // Muscle-group fallbacks
  if (muscle === 'Mobility')     return 'mdi:yoga'
  if (muscle === 'Conditioning') return 'mdi:run-fast'
  if (muscle === 'Cardio')       return 'mdi:heart-pulse'
  if (muscle === 'Calves')       return 'mdi:walk'
  if (muscle === 'Biceps')    return 'mdi:arm-flex'
  if (muscle === 'Triceps')   return 'mdi:arm-flex-outline'
  if (muscle === 'Core')      return 'mdi:yoga'
  if (muscle === 'Rear Delts') return 'mdi:human-greeting'
  if (muscle === 'Lats')      return 'mdi:human-handsup'
  if (muscle === 'Shoulders') return 'mdi:weight-lifter'
  if (muscle === 'Upper Back' || muscle === 'Back') return 'mdi:rowing'
  if (muscle === 'Quads' || muscle === 'Hamstrings' || muscle === 'Glutes') return 'mdi:run'
  if (muscle === 'Chest')     return 'mdi:weight-lifter'

  // Equipment fallbacks
  if (equip === 'Pull-up Bar' || equip === 'Parallel Bars') return 'mdi:human-handsup'
  if (equip === 'Dumbbells')   return 'mdi:dumbbell'
  if (equip === 'Bodyweight')  return 'mdi:human'
  if (equip === 'Cable')       return 'mdi:weight-lifter'

  return 'mdi:weight-lifter'
}

