const DAY_SPLITS = [
  [0,1,2,3], [4,5,6,7], [0,1,8,9],
  [2,3,10,5],[0,4,6,7], [1,8,9,10],[2,5,11,3],
]

export function getTodaysExercises() {
  const day = new Date().getDay()
  const idx = day === 0 ? 6 : day - 1
  return DAY_SPLITS[idx].map(i => EXERCISES[i])
}

export const MUSCLES = ['All','Chest','Back','Lats','Upper Back','Quads','Hamstrings','Glutes','Shoulders','Rear Delts','Biceps','Triceps','Calves','Core','Cardio','Conditioning','Mobility']
